/**
 * Bundles the original surface — React, pdf.js, pdf-lib and `@lexipulse/pdf` — plus its
 * stylesheet into one self-contained HTML asset.
 *
 * Self-contained is not a preference. The page is loaded from `file://` inside a WebView,
 * and Chromium treats a sibling module there as a cross-origin request and blocks it. One
 * classic `<script>` and one `<style>` is the only shape that works, and it is also the
 * shape that works with no network at all.
 *
 * The stylesheet is generated by Tailwind over the package's own sources, because the
 * surface is written in the same utility classes as the website and nothing inside a
 * WebView is going to compile them at runtime. Getting this wrong does not look like a
 * missing colour — without `h-[100dvh]` and `min-h-0` the scroller grows to the height of
 * the whole document and nothing scrolls at all.
 *
 *   node scripts/build-pdf-surface.mjs
 */
import { build } from 'esbuild';
import { mkdirSync, writeFileSync, readFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { createRequire } from 'node:module';
import postcss from 'postcss';
import tailwind from '@tailwindcss/postcss';

const here = dirname(fileURLToPath(import.meta.url));
const projectRoot = resolve(here, '..');
const repoRoot = resolve(projectRoot, '..', '..');
const require = createRequire(import.meta.url);
const pdfjsVersion = JSON.parse(
  readFileSync(require.resolve('pdfjs-dist/package.json'), 'utf8'),
).version;

/* ------------------------------------------------------------------ stylesheet */

/**
 * Base rules the utilities cannot express, plus a dark default.
 *
 * The real colours arrive from the app at runtime — the surface follows whichever theme
 * the reader picked — but the page has to be readable in the frame before that lands.
 */
const BASE_CSS = `
@import 'tailwindcss';
@source '${resolve(repoRoot, 'packages/pdf/src').replace(/\\/g, '/')}';

:root {
  --lx-bg: #000000;
  --lx-surface: #0a0a0b;
  --lx-surface-hover: #141416;
  --lx-border: #1c1c1f;
  --lx-border-strong: #2a2a2e;
  --lx-text: #ededef;
  --lx-text-muted: #9c9ca5;
  --lx-text-faint: #7c7c85;
  --lx-accent: #ff4d4d;
  --lx-accent-strong: #ff6b6b;
  --lx-accent-on: #1a0505;
  --lx-accent-text: #ff4d4d;
  --lx-bg-deep: #18181b;
  color-scheme: dark;
}

html, body, #root {
  height: 100%;
  margin: 0;
  background: var(--lx-bg);
  color: var(--lx-text);
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  font-size: 15px;
  /* A WebView happily bounces the whole page; the surface scrolls its own panes. */
  overscroll-behavior: none;
  -webkit-text-size-adjust: 100%;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border-width: 0;
}

/* The invisible, selectable copy of the page text that pdf.js positions over the canvas. */
.lx-pdf-text-layer {
  position: absolute;
  inset: 0;
  overflow: hidden;
  line-height: 1;
  text-align: initial;
  forced-color-adjust: none;
  transform-origin: 0 0;
  z-index: 2;
}

.lx-pdf-text-layer span,
.lx-pdf-text-layer br {
  position: absolute;
  white-space: pre;
  cursor: text;
  color: transparent;
  transform-origin: 0% 0%;
}

.lx-pdf-text-layer span.markedContent {
  top: 0;
  height: 0;
}

.lx-pdf-text-layer ::selection {
  background: rgba(59, 130, 246, 0.35);
}

.lx-pdf-text-layer .endOfContent {
  display: block;
  position: absolute;
  inset: 100% 0 0;
  z-index: -1;
  cursor: default;
  user-select: none;
}

.lx-slider {
  --lx-slider-fill: 0%;
  accent-color: var(--lx-accent);
}

/* Controls are touched, not clicked: 8 px taller than the web sizes, without changing
   the layout the utilities produce. */
button, input, select, textarea {
  font: inherit;
  touch-action: manipulation;
}
`;

const css = await postcss([tailwind()]).process(BASE_CSS, { from: resolve(here, 'surface.css') });

/* --------------------------------------------------------------------- script */

const result = await build({
  entryPoints: [resolve(here, 'pdf-surface-entry.tsx')],
  bundle: true,
  format: 'iife',
  jsx: 'automatic',
  // Android WebView and WKWebView are both evergreen, but the legacy pdf.js build already
  // targets older syntax; matching it keeps the output uniform.
  target: ['chrome90', 'safari15'],
  minify: true,
  legalComments: 'none',
  define: { 'process.env.NODE_ENV': '"production"' },
  write: false,
  logLevel: 'warning',
});

const js = result.outputFiles[0].text;

// A literal `</script>` anywhere in the bundle would end the tag early. Splitting the
// sequence is the standard, behaviour-preserving fix.
const safeJs = js.replace(/<\/script/gi, '<\\/script');
const safeCss = css.css.replace(/<\/style/gi, '<\\/style');

const html = `<!doctype html>
<html lang="de">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover,maximum-scale=1">
<title>LexiPulse</title>
<!-- Generated by scripts/build-pdf-surface.mjs. pdfjs-dist ${pdfjsVersion}. Do not edit. -->
<style>${safeCss}</style>
</head>
<body>
<div id="root"></div>
<script>${safeJs}</script>
</body>
</html>
`;

const outDir = resolve(projectRoot, 'assets', 'pdfjs');
mkdirSync(outDir, { recursive: true });
writeFileSync(resolve(outDir, 'pdf-surface.html'), html, 'utf8');

process.stdout.write(
  `wrote assets/pdfjs/pdf-surface.html — ${(html.length / 1024).toFixed(0)} KB ` +
    `(css ${(safeCss.length / 1024).toFixed(0)} KB), pdfjs-dist ${pdfjsVersion}\n`,
);
